describe('Returning User Login - Secure Area Access', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/login');
  });

  it('should successfully log in a returning user and access secure area', () => {
    cy.get('[name="username"]').type('tomsmith');
    cy.get('[name="password"]').type('SuperSecretPassword!');
    cy.get('[type="submit"]').click();
    cy.url().should('include', '/secure');
    cy.get('[data-testid="flash-messages"]').should('be.visible');
    cy.get('[data-testid="flash-messages"]').should('contain', 'You logged into a secure area!');
    cy.get('[data-testid="content"]').should('be.visible');
    cy.get('[data-testid="content"]').should('contain', 'Welcome');
  });

  it('should display error message when login fails with invalid credentials', () => {
    cy.get('[name="username"]').type('tomsmith');
    cy.get('[name="password"]').type('WrongPassword');
    cy.get('[type="submit"]').click();
    cy.url().should('include', '/login');
    cy.get('[data-testid="flash-messages"]').should('be.visible');
    cy.get('[data-testid="flash-messages"]').should('contain', 'Invalid username or password');
    cy.get('[data-testid="content"]').should('not.exist');
  });
});
